import { useCallback, useEffect, useRef, useState } from "react";

export interface LocalJudgeTransport {
  ask: (
    question: string,
    thread: string | null,
  ) => Promise<{ id: string; text: string }>;
  speak: (messageId: string) => Promise<Blob>;
}
type Options = {
  transport?: LocalJudgeTransport;
  onMessage: (event: {
    message: string;
    role: "user" | "agent";
    event_id: string;
  }) => void;
  onError: (message: string) => void;
};

/** Same conversation UI, with every substantive answer generated by the saved local Judge. */
export function useLocalJudgeConversation(options: Options) {
  const current = useRef(options);
  current.current = options;
  const [status, setStatus] = useState<
    "disconnected" | "connecting" | "connected" | "error"
  >("disconnected");
  const [isSpeaking, setSpeaking] = useState(false);
  const [isThinking, setThinking] = useState(false);
  const [isMuted, setMutedState] = useState(false);
  const state = useRef({
    generation: 0,
    connected: false,
    muted: false,
    busy: false,
    textOnly: false,
    thread: null as string | null,
    input: 0,
    output: 0,
  });
  const stream = useRef<MediaStream | null>(null);
  const audioContext = useRef<AudioContext | null>(null);
  const recorder = useRef<MediaRecorder | null>(null);
  const timer = useRef<ReturnType<typeof setInterval> | null>(null);
  const outputTimer = useRef<ReturnType<typeof setInterval> | null>(null);
  const playback = useRef<HTMLAudioElement | null>(null);
  const audioUrl = useRef<string | null>(null);
  const abort = useRef<AbortController | null>(null);
  const endSession = useCallback(() => {
    state.current.generation++;
    state.current.connected = false;
    state.current.busy = false;
    abort.current?.abort();
    if (timer.current) clearInterval(timer.current);
    timer.current = null;
    if (outputTimer.current) clearInterval(outputTimer.current);
    outputTimer.current = null;
    if (recorder.current?.state === "recording") recorder.current.stop();
    recorder.current = null;
    stream.current?.getTracks().forEach((track) => track.stop());
    stream.current = null;
    playback.current?.pause();
    playback.current = null;
    if (audioUrl.current) URL.revokeObjectURL(audioUrl.current);
    audioUrl.current = null;
    void audioContext.current?.close();
    audioContext.current = null;
    state.current.input = state.current.output = 0;
    setSpeaking(false);
    setThinking(false);
    setStatus("disconnected");
  }, []);
  useEffect(() => endSession, [endSession]);

  const send = useCallback(async (question: string, generation: number) => {
    if (!current.current.transport || generation !== state.current.generation)
      return;
    state.current.busy = true;
    setThinking(true);
    try {
      const reply = await current.current.transport.ask(
        question,
        state.current.thread,
      );
      if (generation !== state.current.generation) return;
      current.current.onMessage({
        message: reply.text,
        role: "agent",
        event_id: reply.id,
      });
      if (!state.current.textOnly) {
        const blob = await current.current.transport.speak(reply.id);
        if (generation !== state.current.generation) return;
        if (audioUrl.current) URL.revokeObjectURL(audioUrl.current);
        audioUrl.current = URL.createObjectURL(blob);
        const audio = new Audio(audioUrl.current);
        playback.current = audio;
        const ctx = audioContext.current;
        if (ctx) {
          const source = ctx.createMediaElementSource(audio);
          const meter = ctx.createAnalyser();
          meter.fftSize = 256;
          source.connect(meter);
          meter.connect(ctx.destination);
          const bytes = new Uint8Array(meter.frequencyBinCount);
          outputTimer.current = setInterval(() => {
            meter.getByteFrequencyData(bytes);
            state.current.output =
              bytes.reduce((sum, n) => sum + n, 0) / bytes.length / 255;
          }, 80);
        }
        setThinking(false);
        setSpeaking(true);
        await new Promise<void>((resolve, reject) => {
          audio.onended = () => resolve();
          audio.onpause = () => resolve();
          audio.onerror = () =>
            reject(
              new Error(
                "Judge audio could not play. Try another question or use text.",
              ),
            );
          audio.play().catch(reject);
        });
      }
    } catch (error) {
      if (generation === state.current.generation)
        current.current.onError(
          error instanceof Error
            ? error.message
            : "The local Judge could not finish this turn.",
        );
    } finally {
      if (generation === state.current.generation) {
        if (outputTimer.current) clearInterval(outputTimer.current);
        outputTimer.current = null;
        playback.current = null;
        if (audioUrl.current) URL.revokeObjectURL(audioUrl.current);
        audioUrl.current = null;
        state.current.busy = false;
        state.current.output = 0;
        setThinking(false);
        setSpeaking(false);
      }
    }
  }, []);

  const startSession = useCallback(
    async ({
      textOnly,
      thread,
    }: {
      textOnly: boolean;
      thread: string | null;
    }) => {
      endSession();
      const generation = state.current.generation;
      state.current.textOnly = textOnly;
      state.current.thread = thread;
      state.current.muted = false;
      setMutedState(false);
      setStatus("connecting");
      try {
        if (!textOnly) {
          // Unlock output during the PM's click, before microphone permission
          // or network requests can consume the browser's user activation.
          const ctx = new AudioContext();
          audioContext.current = ctx;
          await ctx.resume();
          if (generation !== state.current.generation) return;
          const mic = await navigator.mediaDevices.getUserMedia({
            audio: {
              echoCancellation: true,
              noiseSuppression: true,
              autoGainControl: true,
            },
          });
          if (generation !== state.current.generation) {
            mic.getTracks().forEach((t) => t.stop());
            return;
          }
          stream.current = mic;
          const input = ctx.createMediaStreamSource(mic),
            meter = ctx.createAnalyser();
          meter.fftSize = 1024;
          input.connect(meter);
          const samples = new Float32Array(meter.fftSize);
          let heardAt = 0,
            startedAt = 0;
          timer.current = setInterval(() => {
            meter.getFloatTimeDomainData(samples);
            const rms = Math.sqrt(
              samples.reduce((sum, n) => sum + n * n, 0) / samples.length,
            );
            state.current.input =
              state.current.muted || state.current.busy
                ? 0
                : Math.min(1, rms * 5);
            if (state.current.muted || state.current.busy) return;
            const now = performance.now();
            if (rms > 0.018) {
              heardAt = now;
              if (!recorder.current || recorder.current.state === "inactive") {
                const mimeType = [
                  "audio/webm;codecs=opus",
                  "audio/mp4",
                  "audio/ogg;codecs=opus",
                ].find((type) => MediaRecorder.isTypeSupported(type));
                const recording = new MediaRecorder(
                  mic,
                  mimeType ? { mimeType } : undefined,
                );
                const chunks: Blob[] = [];
                recorder.current = recording;
                startedAt = now;
                recording.ondataavailable = (event) => {
                  if (event.data.size) chunks.push(event.data);
                };
                recording.onstop = async () => {
                  if (
                    generation !== state.current.generation ||
                    state.current.muted
                  )
                    return;
                  state.current.busy = true;
                  setThinking(true);
                  try {
                    const controller = new AbortController();
                    abort.current = controller;
                    const response = await fetch("/api/voice/transcribe", {
                      method: "POST",
                      body: new Blob(chunks, { type: recording.mimeType }),
                      headers: { "Content-Type": recording.mimeType },
                      signal: controller.signal,
                    });
                    const result = await response.json();
                    if (!response.ok)
                      throw new Error(
                        result.detail || "Speech transcription failed.",
                      );
                    if (generation !== state.current.generation) return;
                    current.current.onMessage({
                      message: result.text,
                      role: "user",
                      event_id: crypto.randomUUID(),
                    });
                    await send(result.text, generation);
                  } catch (error) {
                    if (generation === state.current.generation)
                      current.current.onError(
                        error instanceof Error
                          ? error.message
                          : "Could not transcribe your question.",
                      );
                  } finally {
                    if (generation === state.current.generation) {
                      state.current.busy = false;
                      setThinking(false);
                    }
                  }
                };
                recording.start();
              }
            }
            if (
              recorder.current?.state === "recording" &&
              (now - heardAt > 1100 || now - startedAt > 45000)
            )
              recorder.current.stop();
          }, 80);
        }
        if (generation !== state.current.generation) return;
        state.current.connected = true;
        setStatus("connected");
      } catch (error) {
        if (generation !== state.current.generation) return;
        endSession();
        setStatus("error");
        current.current.onError(
          error instanceof Error
            ? error.message
            : "Could not open the microphone.",
        );
      }
    },
    [endSession, send],
  );

  return {
    status,
    isSpeaking,
    isThinking,
    isMuted,
    isListening:
      status === "connected" && !isMuted && !isThinking && !isSpeaking,
    startSession,
    endSession,
    setMuted: (muted: boolean) => {
      state.current.muted = muted;
      setMutedState(muted);
      if (muted && recorder.current?.state === "recording")
        recorder.current.stop();
    },
    sendUserMessage: (question: string) => {
      if (!state.current.connected || state.current.busy) return;
      void send(question, state.current.generation);
    },
    sendUserActivity: () => {},
    sendContextualUpdate: () => {},
    getInputVolume: () => state.current.input,
    getOutputVolume: () => state.current.output,
  };
}
